// Packs the Minepanda client and its libraries into one self-contained file, dist/minepanda.lua,
// so it can be dropped into community operating systems that don't provide the CraftOS shell's require.
// Run from the repository root: node tools/bundle-client.js
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const source = path.join(root, "minepanda");
const output = path.join(root, "dist", "minepanda.lua");

// Every module the client requires, in load order. ROM modules such as cc.strings stay external.
const modules = ["lib.common", "lib.ui"];

function read(file) {
	return fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n").trimEnd();
}

const parts = [
	"-- Minepanda customer app, bundled into a single file.",
	"-- Generated by tools/bundle-client.js from minepanda/client.lua. Edit those sources, not this file.",
	"local Modules = {}",
	"local Loaded = {}",
	"local NativeRequire = require",
	"",
	"-- Bundled modules first, then the system's require, then the ROM directly for OSes without one.",
	"local function BundleRequire(Name)",
	"\tif (Loaded[Name] ~= nil) then return Loaded[Name] end",
	"",
	"\tif (Modules[Name]) then",
	"\t\tLoaded[Name] = Modules[Name](Name)",
	"\telseif (NativeRequire) then",
	"\t\tLoaded[Name] = NativeRequire(Name)",
	"\telse",
	"\t\tLoaded[Name] = dofile(\"/rom/modules/main/\" .. Name:gsub(\"%.\", \"/\") .. \".lua\")",
	"\tend",
	"",
	"\treturn Loaded[Name]",
	"end",
	"",
	"local require = BundleRequire",
	""
];

for (const name of modules) {
	const file = path.join(source, ...name.split(".")) + ".lua";
	parts.push(`Modules["${name}"] = function(...)`, read(file), "end", "");
}

parts.push(read(path.join(source, "client.lua")), "");

fs.mkdirSync(path.dirname(output), { recursive: true });
fs.writeFileSync(output, parts.join("\n"));
console.log(`Wrote ${path.relative(root, output)}`);
